"""Generate a consolidated report strictly from recorded experiments."""
import csv
import json
from datetime import datetime
from html import escape
from pathlib import Path
import numpy as np
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.utils import ImageReader
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak, KeepTogether
from .experiments import ROOT, RESULTS, model_factory

def main(eda_path=None):
    models=json.loads((RESULTS/'models.json').read_text()); final=json.loads((RESULTS/'final.json').read_text()); eda=json.loads((Path(eda_path) if eda_path else RESULTS/'eda.json').read_text())
    out=ROOT/'output'/'pdf';out.mkdir(parents=True,exist_ok=True)
    styles=getSampleStyleSheet()
    styles.add(ParagraphStyle(name='BodySmall',parent=styles['BodyText'],fontSize=9,leading=13,spaceAfter=9))
    styles['Title'].textColor=colors.HexColor('#124b67');styles['Heading1'].textColor=colors.HexColor('#124b67');styles['Heading2'].textColor=colors.HexColor('#16866e')
    story=[]
    def p(text): story.append(Paragraph(text,styles['BodySmall']))
    def h(text): story.append(Paragraph(text,styles['Heading1']))
    def sub(text): story.append(Paragraph(text,styles['Heading2']))
    def image(name,width=480):
        path=RESULTS/'figures'/name
        if path.exists():
            iw,ih=ImageReader(str(path)).getSize();scale=min(width/iw,480/ih);story.append(Image(str(path),width=iw*scale,height=ih*scale));story.append(Spacer(1,10))
    def table(rows,widths=None):
        wrapped=[[Paragraph(escape(str(c)),styles['BodySmall']) for c in row] for row in rows]
        t=Table(wrapped,colWidths=widths,repeatRows=1,hAlign='LEFT')
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e1edf3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.7,colors.HexColor('#124b67')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f5f8fa')]),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7)]))
        story.append(t);story.append(Spacer(1,12))
    def page(): story.append(PageBreak())
    story.append(Paragraph('PathSnap',styles['Title']));story.append(Paragraph('Distributed map matching and route reconstruction',styles['Heading2']))
    p('Technical report | 18 November 2026 | Reproducible local implementation')
    p('This report describes experiments executed on the supplied 80 training and 10 student-test trips. All tables and plots are derived from saved results. No reserved evaluator trips were supplied or used.')
    p('<b>Measured outcome.</b> Tuned histogram gradient boosting plus directed HMM decoding achieved mean-trip Macro F1 0.8191, Top-1 accuracy 86.82%, route-set F1 0.8922 and directed continuity 99.51% on student-test data. These are development results against weak observation labels, not final evaluator scores.')
    p('<b>Important interpretation.</b> The supplied route files are ordered arc sequences, not per-observation labels. A monotone alignment creates weak point labels for training and scoring. This can bias scores, especially around intersections, repeated arcs, stationary observations and noisy reference routes.')
    p('<b>Assistance disclosure.</b> Codex assisted with implementation, experiment execution, testing, visualisation and report drafting. The team must review the analysis, understand the implementation, add its own authorship details and disclose assistance according to the event rules. This document does not claim unaided student authorship.')
    p('<b>Submission status.</b> Local source, trained artifacts, experiments, API, UI and report are prepared. Public GitHub publication and a physical two-laptop receiving-terminal demonstration remain external submission steps. The reserved evaluator partition must be loaded on Laptop 1 when supplied.')
    image('geography.png')
    page();h('1. Dataset understanding and exploratory analysis')
    table([['Partition','Trips','GPS observations','Missing numeric values','Largest gap (s)'],*[ [s.replace('_',' '),v['trips'],v['observations'],v['missing_values'],f"{v['max_gap_seconds']:.0f}"] for s,v in eda.items()]], [110,45,110,110,100])
    p('Each trip has a .track file (longitude, latitude, timestamp), .nodes file (longitude, latitude), .arcs file (directed source and destination node indices) and .route file (ordered arc indices). Arc IDs are local row indices; they cannot be treated as a globally shared multiclass vocabulary.')
    p('The audit reads every supplied trip, validates column counts, finite values, coordinate ranges, nondecreasing timestamps and node-index bounds, and records file bytes, geographic extents, graph connectivity, duplicate timestamps and time gaps in results/inventory.csv. Missing numeric values were zero in both supplied partitions; no imputation was necessary. Invalid new inputs fail explicitly rather than silently dropping observations.')
    p(f"Exactly one-second steps account for {eda['train']['one_second_fraction']:.2%} of training intervals and {eda['student_test']['one_second_fraction']:.2%} of student-test intervals. Training has {eda['train']['trips_with_multiple_components']} graphs with multiple weak components; all ten student-test graphs have multiple weak components. No isolated nodes were found. Disconnected components therefore require explicit decoder handling.")
    p('Longitude/latitude coordinates are converted to a local equirectangular metric plane using Earth radius 6,371,008.8 m and cosine latitude at the trip network centroid. This is appropriate as a local approximation, but not a global projected CRS. Raw coordinates remain available for map display. Large time gaps are retained and decoded with state resets at gaps over 60 seconds; duplicate timestamps also reset the chain.')
    sub('Reference alignment and leakage boundaries')
    p('For each GPS observation, compute its projection distance to every arc position in the ordered reference sequence. Dynamic programming minimises summed squared distances, capped at 2,000 m before squaring, subject to a nondecreasing reference-position constraint. The chain can remain on an arc or skip arcs. Repeated arc occurrences retain separate positions during alignment. The initial and final reference positions are unconstrained. This is weak supervision: chronology helps disambiguate roads but it is not independently verified point truth.')
    p('Candidate construction, features, scoring and decoding take only track/nodes/arcs. API prediction finishes before server-side reference alignment and metrics run. A test corrupts a reference file and confirms inference predictions remain identical. Labels and reference routes never appear in the evaluator UI response. Development Folium maps intentionally show permitted student-test reference routes and are separate from the evaluator UI.')
    sub('Candidate generation and features')
    p('Each observation receives the eight nearest directed segments by metric projection distance. A midpoint KD-tree provides a seed radius; the seed kth distance plus half the longest segment bounds a second radius query. Exact segment distances then rank the resulting pool, breaking ties by arc ID. This radius bound avoids silently missing long segments. Networks with fewer than eight arcs use every available arc; empty networks fail validation.')
    p('Eleven features describe GPS-to-segment distance, directed heading disagreement (1-cosine), projection fraction, segment length, observed speed, previous time gap, distance rank, distance above nearest candidate, previous-observation distance, next-observation distance and whether movement is sufficient to estimate heading. Heading uses centred differences; consequently the pipeline is offline rather than causal streaming. GPS and road geometry alone determine every feature.')
    page();h('2. Experimental design and overall comparison')
    p('Training uses up to 200 uniformly spaced observations per training trip and all eight candidates per sampled observation. This bounds fitting cost and gives trips similar training budgets; validation and student-test metrics use every observation. Candidate classification is binary: reference arc versus other candidate. A reference missing from the candidate set produces no positive candidate and remains a miss in evaluation. No reference candidate is forcibly inserted.')
    p('Three-fold GroupKFold splits by trip ID across the 80 training trips. Scaling, when used, is fitted only inside each training fold. The final model is selected by the mean of three fold scores, where each fold score averages per-trip arc Macro F1. Per-trip Macro F1 uses the union of predicted and reference local arc IDs; scores are averaged over trips so a long trip does not dominate. Top-1 accuracy is also averaged over trips. Candidate miss rate averages trip miss fractions. Candidate log loss uses normalised positive-class scores; a missing reference gets probability 1e-15. These are operational definitions, not organiser-provided point labels.')
    rows=[['Model','CV Macro F1','Test Top-1','Test Macro F1','Log loss','Continuity','Score time (s)']]
    for name,r in models.items():
        a=r['student_test']['aggregate'];rows.append([name,f"{r['cv_macro_f1']:.4f}",f"{a['top1_accuracy']:.4f}",f"{a['macro_f1']:.4f}",f"{a['log_loss']:.4f}",f"{a['route_continuity']:.4f}",f"{a['inference_seconds']:.3f}"])
    table(rows,[115,60,60,65,55,60,60])
    p('Score time sums candidate scoring across the ten student-test trips; it excludes loading, candidate generation, continuity diagnostics, alignment and API serialisation. End-to-end HTTP timing is recorded separately. Route continuity is the fraction of consecutive nongap observations connected through directed shortest paths within a search budget max(300 m, 3 x observed displacement + 100 m, 50 m/s x time interval), including segment offsets. This is bounded reachability, not a guarantee of plausible speed or exact adjacent endpoints.')
    image('model_comparison.png')
    p('Gradient boosting leads grouped CV (0.7369), narrowly ahead of the forest (0.7342). Both outperform the linear and Gaussian models, supporting nonlinear interactions among geometry, rank and movement. The tree has competitive Top-1 accuracy but worse probability loss than the ensembles. Student-test values exceed CV for all five models; this difference alone does not establish an absence of overfitting because the partitions differ.')
    page();h('3. Model-specific experiments')
    descriptions={
      'LogisticRegression':('Linear probabilistic','StandardScaler; C=1; max_iter=500; seed=352','Binary logistic log loss with L2 regularisation','A small, interpretable probability baseline for distance and heading. A linear boundary misses nonlinear interactions, as shown by its lower CV F1 than the tree ensembles.'),
      'GaussianNB':('Probabilistic generative','StandardScaler; var_smoothing=1e-9','Maximum-likelihood class priors and independent Gaussian feature likelihoods','Fast generative scoring is a useful contrast to discriminative training. Correlated distance/rank features violate conditional independence; its relatively poor log loss signals problematic probability quality.'),
      'DecisionTree':('Single tree','max_depth=12; min_samples_leaf=20; seed=352','Greedy Gini impurity reduction','Captures nonlinear geometric thresholds without scaling. A single tree is unstable and probabilities in leaves can be extreme; its higher test log loss than the forest supports this concern.'),
      'RandomForest':('Bagged ensemble','64 trees; max_depth=16; min_samples_leaf=8; max_features=0.8; seed=352','Bootstrap trees with Gini split objective; averaged class probabilities','Averaging trees reduces sensitivity to individual splits and handles nonlinear interactions. It improves CV F1 over a single tree, at larger storage and scoring cost.'),
      'HistGradientBoosting':('Boosting','max_iter=100; max_leaf_nodes=15; learning_rate=0.1; L2=1; seed=352','Binary log loss via histogram gradient boosting','Sequential corrections capture nonlinear candidate geometry efficiently. It has the best baseline CV F1 and test log loss, but the small margin over the forest means superiority should not be overstated.')}
    for name,r in models.items():
        model_start=len(story)
        family,config,loss,why=descriptions[name];a=r['student_test']['aggregate'];cm=np.array(r['student_test']['candidate_confusion_matrix']);candidate_accuracy=np.trace(cm)/cm.sum()
        sub(name+' / '+family)
        p(why);p('<b>Initial configuration:</b> '+config+'. <b>Objective:</b> '+loss+'.')
        p(f"<b>Observed student-test results:</b> Top-1 {a['top1_accuracy']:.4f}; arc Macro F1 {a['macro_f1']:.4f}; precision {a['macro_precision']:.4f}; recall {a['macro_recall']:.4f}; candidate log loss {a['log_loss']:.4f}. Grouped CV fold F1 values: {', '.join(f'{v:.4f}' for v in r['cv_fold_macro_f1'])}. Fitting plus CV took {r['training_and_cv_seconds']:.2f} s.")
        p(f"<b>Fit diagnosis:</b> sampled training binary candidate accuracy {r['train_sample_candidate_accuracy']:.4f}; test binary candidate-selection diagnostic accuracy {candidate_accuracy:.4f}. These differ in decision rule (binary threshold versus one selected arc), so they are not a formal generalisation gap. The primary evidence is the trip-held-out CV distribution. No claim of proven overfitting or underfitting follows from candidate accuracy alone. {('The weaker held-out F1 relative to nonlinear ensembles is consistent with restrictive model assumptions.' if name in ['LogisticRegression','GaussianNB'] else 'Depth/leaf regularisation controls complexity, but repeated geographic areas across trips can still make CV optimistic. A geographic holdout was not performed.')}")
        story[model_start:]=[KeepTogether(story[model_start:])]
    image('confusion.png')
    p('The confusion figures show candidate-level positive/negative selection counts for each trained model. They are diagnostics, not a merged global arc confusion matrix, since arc IDs are trip-local. These estimators do not expose meaningful epoch-wise loss histories in this experiment; no artificial training curves are supplied.')
    page();h('4. Bayesian hyperparameter optimisation')
    p('The chosen family is histogram gradient boosting. Optuna TPE runs ten actual trials with seed 352 and three startup trials; subsequent proposals adapt to observed objective values. Every trial uses the same trip-grouped folds and observation budget as the baselines. Objective: maximise mean fold, mean trip Macro F1 on training-only held-out trips. Student-test labels are not used by the tuning objective.')
    with (RESULTS/'bayesian_trials.csv').open(newline='',encoding='utf-8') as stream:
        trial_rows=list(csv.DictReader(stream))
    search_seconds=sum((datetime.fromisoformat(row['datetime_complete'])-datetime.fromisoformat(row['datetime_start'])).total_seconds() for row in trial_rows)
    p(f'The ten recorded optimisation trials consumed {search_seconds:.2f} seconds in total, excluding initial candidate preparation and final refitting. Baseline fitting plus cross-validation consumed {sum(r["training_and_cv_seconds"] for r in models.values()):.2f} seconds across the five families.')
    table([['Parameter','Search space','Best value'],['learning_rate','Log-uniform [0.025, 0.25]',final['best_params']['learning_rate']],['max_leaf_nodes','Integer [7, 31]',final['best_params']['max_leaf_nodes']],['l2_regularization','Log-uniform [0.01, 10]',final['best_params']['l2_regularization']],['max_iter','Integer [60, 160]',final['best_params']['max_iter']]],[135,190,150])
    base=models[final['selected']];tuned=final['tuned_student_test']['aggregate'];untuned=base['student_test']['aggregate']
    table([['Metric','Untuned','Tuned'],['CV Macro F1',f"{base['cv_macro_f1']:.4f}",f"{final['best_cv_macro_f1']:.4f}"],*[ [key,f'{untuned[key]:.4f}',f'{tuned[key]:.4f}'] for key in ['top1_accuracy','macro_f1','log_loss','inference_seconds']]],[210,130,135])
    image('search.png')
    p('Tuning gives a small CV improvement of 0.00136 absolute F1 and a small student-test improvement. There is no evidence of a large or statistically established improvement. The tuned model is refitted on the complete sampled training set and retained because its CV score exceeds baseline. results/bayesian_trials.csv stores all trials and fold scores; bayesian_search.sqlite3 retains the optimiser record. Trial durations provide search cost; timing is hardware dependent.')
    page();h('5. HMM and Viterbi reconstruction')
    p('Hidden states are the candidate directed arc IDs at each GPS observation. The selected binary classifier produces positive-class scores; clipping and within-observation normalisation produce emission masses. Viterbi maximises the sum of log emission and transition compatibility scores, retaining backpointers. Candidate identity and projection fraction remain linked throughout decoding.')
    p('A directed adjacency list and bounded Dijkstra searches compute transition distance: remaining distance on the first arc, shortest path from its end node to the next arc start, and distance along the next arc to its projected point. Forward movement on the same arc uses the fraction difference. Transition log potential is -abs(network distance - observed displacement)/beta. Unreachable transitions receive -18, allowing recovery with an explicitly penalised discontinuity. These are unnormalised HMM-style transition potentials; the method optimises a coherent chain score rather than calibrated Markov likelihoods.')
    p('Gaps above 60 seconds and nonpositive time differences reset the state chain. No candidate can be found only when the network is empty or malformed, which produces a validation error; otherwise nearest segments are returned even when far away. There is no radius-based confidence guarantee. For display, directed shortest-path arcs are inserted between selected segments when reachable within 5 km. Otherwise a break is recorded and no fabricated connecting line is drawn. Geometry bridging is a display reconstruction and does not alter point predictions.')
    a=final['classifier_only']['aggregate'];b=final['hmm']['aggregate']
    table([['Student-test metric','Classifier only','Classifier + HMM'],*[ [key,f'{a[key]:.4f}',f'{b[key]:.4f}'] for key in ['top1_accuracy','macro_f1','macro_precision','macro_recall','route_set_f1','route_continuity','inference_seconds']]],[210,130,135])
    p(f"The decoder beta was chosen from 15, 30 and 60 m on student-test Macro F1; {final['decoder_beta']:.0f} m won. This makes the reported decoder results development estimates. Route-set F1 compares unique selected arc IDs to unique supplied route arc IDs; it does not measure ordering or include display-only bridge arcs. Candidate miss rate is {a['candidate_miss_rate']:.3%}, an important ceiling on point matching. HMM sequence log loss is N/A: the decoder returns a MAP chain, not posterior marginals. The classifier emission log loss remains {a['log_loss']:.4f}.")
    image('decoder.png')
    p('HMM improves arc Macro F1 and route continuity but reduces Top-1 accuracy. It can favour a connected road through ambiguous or stationary GPS observations even when weak alignment assigns another arc; frequent observations can lose accuracy while rarer route segments improve recall. Finite penalties still permit disconnected choices. Large GPS gaps, inaccurate route labels and the fixed eight-candidate set remain limitations. No claim of exact full-sequence reconstruction is made.')
    page();h('6. Geographical visualisation')
    p('The Folium map is generated from student-test trip 00000000, selected by fixed ordering. It includes raw GPS (blue), directed road segments (grey), supplied reference route (purple) and reconstructed prediction (green), plus a legend, layer controls and fitted bounds. Reference layers belong only to the development map. The evaluator UI receives road geometry and predictions, never the reference route.')
    image('folium_screenshot.jpg')
    p('Browser screenshot of the actual generated Folium HTML. The interactive artifact is results/maps/student_test_00000000.html. Map JavaScript and OpenStreetMap tiles require network access; the separate canvas evaluator UI needs no map CDN. The static geography plot on the cover is generated from the same trip and geometry.')
    page();h('7. API, UI and deployment')
    p('Laptop 1 runs FastAPI and loads saved artifacts/model.joblib plus config.json. GET /health reports model readiness; GET /trips discovers the configured evaluation inputs; POST /predict accepts trip_id and an optional evaluate flag. The API generates candidates, scores them, runs Viterbi, reconstructs geometry, then optionally computes reference-based metrics in a separate final step. Request logs print trip ID, observation count, latency and metric summary on the receiving server.')
    p('Laptop 2 serves the ui/ folder on port 8501. Its app-style workspace provides a searchable trip library, server status, layer switches, pan/zoom/fit controls, start/end markers and GeoJSON/JSON exports. The evaluator enters Laptop 1\'s LAN address, selects a discovered trip and reconstructs its route. Metric cards display accuracy, Macro F1, observation count and inference time; diagnostics include precision, recall, route breaks and gap resets. Loading, error and missing-reference states are explicit. Predictions and metrics come from the API; no route outputs are hardcoded.')
    image('ui_screenshot.jpg')
    checks=json.loads((RESULTS/'api_checks.json').read_text())
    p(f"<b>Executed integration checks:</b> {checks['passed']}/10 supplied student-test trips returned HTTP 200 with one predicted arc and snapped point per observation, consistent geometry lengths, and no reference-label fields. All ten trips also reconstructed through the redesigned browser UI. Browser checks covered search, zoom/fit, layer controls, downloads, failed connection and recovery, and 390px/1280px layouts. Downloaded geometry was checked against result JSON. Four algorithm/API tests previously passed. These tests used separate local UI/API ports, not two physical laptops. Evidence is retained in results/frontend_checks.json.")
    page();sub('Deployment procedure and remaining evidence')
    p('Install Python 3.11 and requirements.txt. On Laptop 1 run python run.py serve --host 0.0.0.0 --port 8000. On Laptop 2 run python run.py ui --host 0.0.0.0 --port 8501, open its localhost:8501 and enter http://LAPTOP1_IP:8000. Use a trusted shared LAN and allow the server port if prompted by the OS. Set PATHSNAP_EVAL_DIR on Laptop 1 to the reserved trip directory, containing the same trip subfolder layout; the API discovers the ten options without retraining. Keep route files on Laptop 1.')
    p('The API response evidence below is a real saved HTTP result summary, not a screenshot of a receiving laptop terminal. Capture that terminal during the physical demonstration, as required by the supplied rubric. A physical second laptop and reserved evaluator data were unavailable in this workspace. Docker configuration is included but was not executed. Public repository publication requires an authenticated GitHub account and destination; no repository URL is claimed.')
    sample=json.loads((RESULTS/'api_sample_summary.json').read_text())
    p('<b>Successful API response:</b> '+escape(json.dumps(sample)))
    page();h('8. Reproduction, limitations and traceability')
    table([['Artifact','Purpose'],['results/inventory.csv, eda.json','Full supplied-data audit'],['results/protocol.json','Feature list, fold membership and metric definitions'],['results/models.json','Five model configurations, CV folds and per-trip results'],['results/bayesian_trials.csv, bayesian_search.sqlite3','Bayesian trial evidence'],['results/hmm.json, final.json','Decoder sweep and tuned/untuned results'],['results/api_checks.json','Real HTTP checks for all ten student trips'],['artifacts/*.joblib, config.json','Trained baseline, tuned and final model assets'],['pathsnap/, ui/, tests/, scripts/','Complete implementation and verification'],['results/maps/, results/figures/','Interactive map and actual plots']],[230,245])
    p('Reproduce with python run.py explore; python run.py train --trials 10; python -c "import run; from pathsnap.visuals import main; main()"; python run.py verify. Run the API and python scripts/check_api.py before regenerating this report. Cached trip preprocessing speeds repeated execution; remove the cache after changing feature or alignment logic. The fixed seed controls model and search randomness; operating-system scheduling and library versions can affect timing and tiny numeric differences.')
    p('Limitations: derived point labels are imperfect; decoder selection reuses development data; cross-validation is by trip rather than geography; only 200 observations per trip are used for fitting; transition potentials are not calibrated probabilities; nearest candidates can be far off-network; long-segment radius queries can be expensive; finite disconnect penalties and bounded search can produce breaks. Local unit/integration/browser tests establish the checked behaviours and do not guarantee an error-free system on every unseen trip.')
    p('The report was generated programmatically from recorded experiment files. Team members should verify the weak-label assumptions, review per-trip failures, practise explaining the candidate-to-arc mapping and Viterbi recurrence, and complete the external publication and demonstration steps. No fabricated metric, training curve, evaluator result, public repository or physical-laptop screenshot is included.')
    def footer(canvas,doc):
        canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#526678'));canvas.drawString(40,25,'PathSnap | Executed experiments on supplied development data');canvas.drawRightString(555,25,str(doc.page))
    doc=SimpleDocTemplate(str(out/'PathSnap_Technical_Report.pdf'),pagesize=(595.28,841.89),rightMargin=40,leftMargin=40,topMargin=40,bottomMargin=42,title='PathSnap Technical Report',author='PathSnap project - AI assistance disclosed')
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
    print(out/'PathSnap_Technical_Report.pdf')
